window.ScripturaLexicons.BDAG_PART_0354 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-01\" data-source=\"BDAG\" data-search=\"ταῦρος, ου, ὁ substantivo masculino touro; boi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταῦρος, ου, ὁ</td><td>substantivo masculino</td><td>touro; boi</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-02\" data-source=\"BDAG\" data-search=\"ταὐτά forma contraída variante de τὰ αὐτά BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταὐτά</td><td>forma contraída</td><td>variante de τὰ αὐτά</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-03\" data-source=\"BDAG\" data-search=\"ταφή, ῆς, ἡ substantivo feminino sepultamento; lugar de sepultamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταφή, ῆς, ἡ</td><td>substantivo feminino</td><td>sepultamento; lugar de sepultamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-04\" data-source=\"BDAG\" data-search=\"τάφος, ου, ὁ substantivo masculino sepulcro; túmulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάφος, ου, ὁ</td><td>substantivo masculino</td><td>sepulcro; túmulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-05\" data-source=\"BDAG\" data-search=\"τάχα advérbio talvez; possivelmente; provavelmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάχα</td><td>advérbio</td><td>talvez; possivelmente; provavelmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-06\" data-source=\"BDAG\" data-search=\"τάχειον remissão grafia itacística de τάχιον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάχειον</td><td>remissão</td><td>grafia itacística de τάχιον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-07\" data-source=\"BDAG\" data-search=\"ταχέως advérbio rapidamente; logo; sem demora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταχέως</td><td>advérbio</td><td>rapidamente; logo; sem demora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-08\" data-source=\"BDAG\" data-search=\"ταχινός, ή, όν adjetivo rápido; iminente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταχινός, ή, όν</td><td>adjetivo</td><td>rápido; iminente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-09\" data-source=\"BDAG\" data-search=\"τάχιον, τάχιστα remissão ver ταχέως BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάχιον, τάχιστα</td><td>remissão</td><td>ver ταχέως</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-10\" data-source=\"BDAG\" data-search=\"τάχος, ους, τό substantivo neutro rapidez; pressa; pouco tempo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τάχος, ους, τό</td><td>substantivo neutro</td><td>rapidez; pressa; pouco tempo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-11\" data-source=\"BDAG\" data-search=\"ταχύνω verbo apressar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταχύνω</td><td>verbo</td><td>apressar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-12\" data-source=\"BDAG\" data-search=\"ταχύς, εῖα, ύ adjetivo rápido; veloz; logo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ταχύς, εῖα, ύ</td><td>adjetivo</td><td>rápido; veloz; logo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-13\" data-source=\"BDAG\" data-search=\"τέ partícula enclítica e; assim; até mesmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέ</td><td>partícula enclítica</td><td>e; assim; até mesmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-14\" data-source=\"BDAG\" data-search=\"τέγος, ους, τό substantivo neutro teto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέγος, ους, τό</td><td>substantivo neutro</td><td>teto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-15\" data-source=\"BDAG\" data-search=\"τέθεικα, τεθεικώς, τέθειται, τεθῆναι remissão ver τίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέθεικα, τεθεικώς, τέθειται, τεθῆναι</td><td>remissão</td><td>ver τίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-16\" data-source=\"BDAG\" data-search=\"τεθλιμμένος remissão ver θλίβω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεθλιμμένος</td><td>remissão</td><td>ver θλίβω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-17\" data-source=\"BDAG\" data-search=\"τεθνάναι, τέθνηκα remissão ver θνῄσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεθνάναι, τέθνηκα</td><td>remissão</td><td>ver θνῄσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-18\" data-source=\"BDAG\" data-search=\"τέθραμμαι, τεθραμμένος remissão ver τρέφω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέθραμμαι, τεθραμμένος</td><td>remissão</td><td>ver τρέφω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-19\" data-source=\"BDAG\" data-search=\"τεθῶ remissão ver τίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεθῶ</td><td>remissão</td><td>ver τίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0354-20\" data-source=\"BDAG\" data-search=\"τεῖχος, ους, τό substantivo neutro muro; muralha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεῖχος, ους, τό</td><td>substantivo neutro</td><td>muro; muralha</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0354-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταῦρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταῦρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; inscr., pap., LXX, Philo, Joseph.) touro, boi como animal sacrificial (Cornutus 22 p. 42, 12; Arrian., Anab. 1, 11, 6; Philo, Omn. Prob. Lib. 102; Jos., Ant. 13, 242) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:13</a> (Diod S 16, 91, 3 <span class=\"greek\">ταῦρος</span> <span class=\"greek\">ἐστεμμένος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:13</a>; 10:4; B 2:5 (Is 1:11). Para grandes banquetes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:4</a>.—B. 154. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταὐτά</h1><div class=\"entry-meta\"><span>forma contraída</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταὐτά</span> = <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτά</span>, somente como v.l. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>, 26; 17:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a> —B-D-F §18; Rob. 208; W-S. §5, 9; W-H. App. 145; HvSoden, D. Schriften des NTs I/2, 1911, 1380f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταφή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταφή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">θάπτω</span>, cf. <span class=\"greek\">τάφος</span>)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> sepultamento (Soph., Hdt.+; OGI 90, 32 [II a.C.]; PSI 328,2 e 5 [III a.C.]; PAmh 125, 1; PTebt 479 al.; LXX: TestJob 40:13; AssMos Fgm. k Denis p. 67; Philo, Mos. 2, 283; Jos., Bell. 4, 317, Ant. 6, 292; 9, 182; Ath. 22, 6) <span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ταφήν</span> pedir o cadáver para sepultamento GPt 2:3 (Diod S 10, 29, 1 <span class=\"greek\">ἵνα</span> <span class=\"greek\">λάβῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ταφήν</span>). <span class=\"greek\">δώσω</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πονηροὺς</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ταφῆς</span> <span class=\"greek\">αὐτοῦ</span> entregarei os ímpios para o seu sepultamento, isto é, para pô-lo no sepulcro (par. a <span class=\"greek\">θάνατος</span>) 1 Cl 16:10 (Is 53:9).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> lugar de sepultamento (2 Ch 26:23 <span class=\"greek\">ἡ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλέων</span>; O. Joach 2, 2; 3, 2 al.; 18, 11 [I a.C.] <span class=\"greek\">ταφὴ</span> <span class=\"greek\">ἰβίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱεράκων</span> ͵<span class=\"greek\">α</span>=‘um lugar de sepultamento para 1,000 múmias de íbis e falcões’. No sentido de ‘sepulcro’, frequentemente em Hdt. et al.; Dt 34:6; Mel., P. 71, 522) <span class=\"greek\">εἰς</span> <span class=\"greek\">ταφὴν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ξένοις</span> como lugar de sepultamento para estrangeiros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:7</a>.—DELG s.v. <span class=\"greek\">θάπτω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάφος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάφος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">θάπτω</span>, cf. <span class=\"greek\">ταφή</span>; em Hom.=‘ritos fúnebres’; geralmente ‘túmulo’)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> lugar ou receptáculo para inumação, sepulcro, túmulo de uma pessoa morta (Hes.+) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:61</a>, 64, 66; 28:1 (EBickermann, Das leere Grab: ZNW 23, 1924, 281–92; Guillaume Baldensperger, Le tombeau vide: RHPR 12, ’32, 413–33; 13, ’33, 105–44; 14, ’34, 97–125; CMasson, Le tomb. v.: RTP 32, ’44, 161–74; HvCampenhausen, D. Ablauf der Osterereignisse u. das leere Grab3 ’66; JKennard, Jr., The Burial of Jesus: JBL 74, ’55, 227–38; WNauck, ZNW 47, ’56, 243–67; LOberlinner, ZNW 73, ’82, 159–82; Finegan s.v. <span class=\"greek\">Ἰούδας</span> 6; v. também <span class=\"greek\">ἀνάστασις</span> 2, final, e <span class=\"greek\">μνημεῖον</span> 2.—Um paralelo externo ao motivo do <span class=\"greek\">τάφος</span> vazio em Chariton 3, 3, 1–4.—Phlegon: 257 Fgm. 36, 1, 9 Jac.: para averiguar se realmente ocorrera uma ressurreição dentre os mortos, abre-se e entra-se em <span class=\"greek\">ὁ</span> <span class=\"greek\">τάφος</span> para ver <span class=\"greek\">πότερον</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κλίνης</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">εὑρήσομεν</span>); GPt 6:24; 8:31; 9:36f; 10:39; 11:45; 13:55. <span class=\"greek\">οἱ</span> <span class=\"greek\">τάφοι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:29</a> (sobre o culto dos sepulcros e a veneração de pessoas piedosas entre os judeus, v. Billerb. I 937f; JJeremias, Heiligengräber in Jesu Umwelt ’58). Sepulcro de Paulo AcPl Ha 10, 18; 11, 13. Sobre <span class=\"greek\">τάφοι</span> <span class=\"greek\">κεκονιαμένοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a>; GNaass 284, 153; v. <span class=\"greek\">κονιάω</span>. No evangelho apócrifo precedente, <span class=\"greek\">τάφ</span>. <span class=\"greek\">κεκ</span>. é empregado metaforicamente. Igualmente <span class=\"greek\">τάφοι</span> <span class=\"greek\">νεκρῶν</span>, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">γέγραπται</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἀνθρώπων</span> sepulcros de mortos, nos quais estão inscritos somente os nomes das pessoas IPhld 6:1. <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τάφῳ</span> chegar ao sepulcro 1 Cl 56:15 (Job 5:26).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> qualquer coisa que funcione como túmulo, túmulo, em imagens variadas: do lugar escuro do qual Deus nos introduz no mundo por ocasião do nascimento 1 Cl 38:3. De animais selvagens que hão de ser o sepulcro de Inácio <span class=\"greek\">ἵνα</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τάφος</span> <span class=\"greek\">γένωνται</span> (isto é, <span class=\"greek\">τὰ</span> <span class=\"greek\">θηρία</span>) IRo 4:2 (Gorgias, Fgm. 5a Diels em <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 3, 2 chama os abutres <span class=\"greek\">ἔμψυχοι</span> <span class=\"greek\">τάφοι</span>). De pessoas pecadoras <span class=\"greek\">τάφος</span> <span class=\"greek\">ἀνεῳγμένος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λάρυγξ</span> (v. <span class=\"greek\">ἀνοίγω</span> 2 e cf. Artem. 1, 80 p. 80, 27 <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">τάφῳ</span> <span class=\"greek\">ἔοικε</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:13</a> (Ps 5:10; 13:3).—B. 294. DELG s.v. <span class=\"greek\">θάπτω</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάχα</span> adv. (<span class=\"greek\">ταχύς</span>; Hom. et al.; também Wsd. 13:6; 14:19; TestJob 22:2 ‘logo’; ApcSed 4:2 <span class=\"greek\">τί</span> <span class=\"greek\">τάχα</span> <span class=\"greek\">ἐποίησας</span>; ‘o que, afinal, realizaste?’) marcador que exprime contingência, variando entre probabilidade e mera possibilidade, talvez, possivelmente, provavelmente (Aeschyl., Hdt. et al.; pap., Wsd., Just., D. 5, 2, com acentuada predominância de <span class=\"greek\">ἄν</span> e do opt. Raramente, como em ambas as passagens do NT, com o indic. e sem <span class=\"greek\">ἄν</span>: Dio Chrys. 15 [32], 33; Ps.-Demetr., El. 180; BGU 1040, 41 [II d.C.] <span class=\"greek\">τάχα</span> <span class=\"greek\">δύνασαι</span>; POxy 40, 7; Wsd 13:6 <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">τάχα</span> <span class=\"greek\">πλανῶνται</span>; Philo, Aet. M. 54; Jos., Ant. 6, 33; 18, 277.—MArnim, De Philonis Byz. dicendi genere, diss. Greifswald 1912, 86; JScham, Der Optativgebrauch bei Klemens v. Alex, 1913, 83; B-D-F §385, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7</a>; Phlm 15.—B. 965. DELG s.v. <span class=\"greek\">ταχύ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχειον</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάχειον</span> (assim, p. ex., POsl 52, 15 [II d.C.]) grafia itacística de <span class=\"greek\">τάχιον</span> (<span class=\"greek\">ταχέως</span>, início).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχέως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταχέως</span> adv. de <span class=\"greek\">ταχύς</span>, positivo (Hom.+; pap., LXX; En 98:16; TestSol 6:5 D; TestAbr.; JosAs cod. A 16, 2 e cap. 19 [p. 63, 5; 69, 6 Bat.]; ApcMos 21).—Comp. <span class=\"greek\">τάχιον</span> ([<span class=\"greek\">ταχεῖον</span> Sod. e Vog.; <span class=\"greek\">τάχειον</span> t.r. Hippocr., Mul. Morb. 1, 2; Epicurus em Diog. L. 10, 98; Diod S 13, 106, 1; frequentemente na fala coloquial em geral, incl. ViHab 8 [p. 86, 11 Sch.]; Jos., Bell. 5, 537, Ant 2, 142 al.; inscr., pap.; Wsd 13:9; 1 Macc 2:40; TestIss 6:3. Esta forma foi rejeitada pelos aticistas; a forma ática <span class=\"greek\">θᾶττον</span> [também 2 Macc; AssMos Fgm. f; Philo, Aet. M. 30; Jos., Ant. 12, 143—WSchmidt 505], que substituiu o homérico <span class=\"greek\">θᾶσσον</span>, encontra-se em nossa lit. somente 1 Cl 65:1a; MPol 13:1.—B-D-F §61, 1; 244, 1; W-S. §11, 3; Mlt-H. 164).—Superl. <span class=\"greek\">τάχιστα</span> somente uma vez (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a> v. 1c abaixo), numa expr. tomada da língua literária (B-D-F §60, 2; 244, 1; 453, 4; Rob. 488; 669.—Alcaeus 70, 15 D.2; Menand., Per. 537 S. [287]; Arrian., Anab. 6, 2, 2; Ael. Aristid. 24, 26 K.=44 p. 833 D.; SIG 1168, 4 [IV a.C.]; PSI 360, 12 [252/251 a.C.]; 792, 10; 3 Macc 1:8; TestSol 6:3 D; Jos., Vi. 16). Em alguns casos pode haver sobreposição semântica entre as acepções 1 e 2.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a um intervalo de tempo muito breve, com foco na rapidez da ação</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> positivo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. em sentido favorável rapidamente, imediatamente, sem demora, logo (Diod S 13, 106, 4; 17, 4, 6; En 98:16; EpArist 291; Jos., Bell. 7, 31; Ant.9, 51) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:21</a>; 15:22 D; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:31</a>; B 3:4; AcPl Ha 3, 4; <span class=\"greek\">οὓτως</span> <span class=\"greek\">ταχέως</span> AcPlCor 2:2 (cf. Gal 1:6 sob <span class=\"greek\">β</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. em sentido de censura demasiado rapidamente, com demasiada facilidade, precipitadamente (Pr 25:8; Wsd 14:28; SibOr Fgm. 1, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:6</a> (cf. AcPlCor 2:2 sob <span class=\"greek\">α</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:22</a>; Pol 6:1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> comp.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. mais rapidamente, mais depressa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:19</a>. <span class=\"greek\">τάχ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Πέτρου</span> mais depressa que Pedro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:4</a>. A comparação é fornecida pelo contexto, mais rapidamente (que os outros), ser o primeiro a … MPol 13:2. <span class=\"greek\">θᾶττον</span> <span class=\"greek\">ἤ</span> mais rapidamente que 13:1. Tão rapidamente quanto possível, o mais cedo possível (TestIss 6:3; Ps.-Clem., Hom. 1, 14) 1 Cl 65:1a (<span class=\"greek\">θᾶττον</span>) e b (<span class=\"greek\">τάχιον</span>). Tanto mais rapidamente MPol 3:1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. sem qualquer ideia de comparação rapidamente, logo, sem demora (PGM 4, 1467 <span class=\"greek\">θᾶττον</span>; Jos., Vi. 310 <span class=\"greek\">θᾶσσον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:27</a>; diferentemente Mussies 128: ‘muito rapidamente’; Hm 10, 1, 6.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> superl. <span class=\"greek\">ὡς</span> <span class=\"greek\">τάχιστα</span> o mais cedo possível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a um ponto futuro no tempo, subsequente a outro ponto no tempo, com foco na brevidade do intervalo, antes que na rapidez da atividade, logo</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> positivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:19</a> (<span class=\"greek\">τ</span>. <span class=\"greek\">πέμπ</span>. como em Plut., Mor. 612e), 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:9</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> comp. <span class=\"greek\">τάχιον</span> sem qualquer ideia de comparação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:14</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:23</a>.—DELG s.v. <span class=\"greek\">ταχύς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταχινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (poético e da prosa tardia em lugar de <span class=\"greek\">ταχύς</span>; Theocr. et al.; CIA III 1344, 3; Cat. Cod. Astr. I 137; LXX; Mel., P. 20, 142)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a um intervalo de tempo muito breve, com foco na rapidez da ação, rápido, apressado <span class=\"greek\">ταχινὸς</span> <span class=\"greek\">γενέσθω</span> Hs 9, 26, 6.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo ao que ocorre sem demora, que vem logo, iminente, célere <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:14</a>; 2:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">μετάνοια</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ταχινὴ</span> <span class=\"greek\">ὀφείλει</span> <span class=\"greek\">εἶναι</span> eles devem arrepender-se logo Hs 8, 9, 4; cf. 9, 20, 4.—DELG s.v. <span class=\"greek\">ταχύς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχιον, τάχιστα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάχιον</span>, <span class=\"greek\">τάχιστα</span> v. <span class=\"greek\">ταχέως</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τάχος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τάχος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. et al.; inscr., pap., LXX; TestSol 7:3 D; Just., D. 68, 3)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> período de tempo muito breve, com foco na rapidez de uma atividade ou acontecimento, velocidade, rapidez, celeridade, pressa, <span class=\"greek\">μετὰ</span> <span class=\"greek\">τάχους</span> com rapidez (Pla., Prot. 332b, Leg. 944c; POxy 2107, 4 [III d.C.]) MPol 13:1.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τάχει</span> (Pind., Aeschyl. et al.; Galen, CMG V/9/2 p. 25, 25 al.; inscr., pap., LXX; Jos., Ant. 6, 163; 17, 83) rapidamente, imediatamente, sem demora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33</a> D; 12:7; 17:15 D; 22:18; 1 Cl 48:1; 63:4.—<span class=\"greek\">τάχει</span> (Tetrast. Iamb. 2, 6, 1 p. 287; SibOr 1, 205; em Plut., Caes. 717 [20, 4], Lys. 438 [11, 2] com o acréscimo de <span class=\"greek\">πολλῷ</span>, <span class=\"greek\">παντί</span>; cf. Just., D. 68, 3 <span class=\"greek\">σὺν</span> <span class=\"greek\">τάχει</span>) rapidamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a> v.l. (v. Tdf.).—<span class=\"greek\">τὸ</span> <span class=\"greek\">τάχος</span> como acus. de especificação, adverbialmente (muito) rapidamente, sem demora (PHib 62, 13; PPetr II, 9, 2, 9; PSI 326, 12; 495, 17; 18 [todos III a.C.]; LXX; Jos., Ant. 13, 8. Sem o art. já em Aeschyl.) 1 Cl 53:2; B 4:8; 14:3 (quanto aos três, cf. Ex 32:7).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a um tempo relativamente breve, subsequente a outro ponto no tempo, <span class=\"greek\">ἐν</span> <span class=\"greek\">τάχει</span> como unidade adverbial logo, em pouco tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:1</a>; 22:6; 1 Cl 65:1; em breve <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:4</a>. Cf. <span class=\"greek\">ταχύς</span> 2.—DELG s.v. <span class=\"greek\">ταχύς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταχύνω</span> fut. 3 sg. <span class=\"greek\">ταχυνεῖ</span> Gen 41:32; aor. <span class=\"greek\">ἐτάχυνα</span> LXX, quase sempre intr. (Aeschyl., X. et al.; LXX; PsSol 17:45) apressar-se, precipitar-se combinado com outro verbo por meio de <span class=\"greek\">καί</span> apressar-se a fazer algo (Judg 13:10) B 4:3.—DELG s.v. <span class=\"greek\">ταχύς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ταχύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ταχύς</span>, <span class=\"greek\">εῖα</span>, <span class=\"greek\">ύ</span> (Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a um período de tempo muito breve, com foco na rapidez de uma atividade ou acontecimento</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> adj. rápido, célere, veloz <span class=\"greek\">ταχ</span>. <span class=\"greek\">καρπός</span> fruto que amadurece rapidamente 2 Cl 20:3. <span class=\"greek\">ταχὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀκοῦσαι</span> pronto para ouvir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a> (Lucian, Epigr. 18 <span class=\"greek\">ταχ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φαγεῖν</span>; Sir 5:11; Libanius, Or. 33 p. 186, 15 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δῆσαι</span> <span class=\"greek\">ταχύς</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρῖναι</span> <span class=\"greek\">βραδύς</span> ‘rápido para prender, mas lento para decidir’; cf. PsSol 4:5 <span class=\"greek\">ταχὺς</span> <span class=\"greek\">εἰσόδῳ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πάσαν</span> <span class=\"greek\">οἰκίαν</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> sobretudo no neut. sing. como adv. <span class=\"greek\">ταχύ</span> (Trag., Hdt.+; pap., LXX; En 97:10; TestSol 4:2 P; Jos., Bell. 7, 394, Vi. 149).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. rapidamente, a um ritmo acelerado <span class=\"greek\">ταχὺ</span> <span class=\"greek\">ἔφυγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:8</a> v.l.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:8</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. sem demora, rapidamente, imediatamente (embora nem sempre seja possível distinguir claramente esta acepção daquela em 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a>; 28:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:2</a> D; 1 Cl 23:5ab (Is 13:22); 53:2 (Ex 32:8; Dt 9:12); Hm 9:7. Provavelmente cabe aqui o <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ταχύ</span> de Rv: 2:5 v.l. (muitos cursivos e textos impressos), 16; 3:11; 11:14; 22:7, 12, 20 (P-ÉLangevin, Jésus Seigneur, ’67, 209–35).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a um tempo relativamente breve, subsequente a outro ponto no tempo, neut. sg. como adv. em pouco tempo, logo (cf. 1b<span class=\"greek\">β</span> acima e <span class=\"greek\">τάχος</span> 2). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:39</a> (logo depois); Hv 3, 8, 9; m 12, 5, 3. Provavelmente cabe aqui também o <span class=\"greek\">μετανοεῖν</span> <span class=\"greek\">ταχύ</span> de Hs 8, 7, 5; 8, 8, 3; 5; 8, 10, 1; 9, 19, 2; 9, 21, 4; 9, 23, 2; <span class=\"greek\">εἰς</span> <span class=\"greek\">ταχεῖαν</span> (sc. <span class=\"greek\">ὥραν</span>) logo AcPlCor 2:3.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέ</h1><div class=\"entry-meta\"><span>partícula enclítica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέ</span> (Hom.+) partícula enclítica (no NT nunca elidida para <span class=\"greek\">τ</span>’. Em Mt três vezes, no ev. de Lucas nove vezes, no ev. de João três vezes [‘sempre contestável textualmente’ B-D-F §443, 1], em Paulo [com acentuada predominância em Ro] mais de vinte vezes, quase com a mesma frequência em Hb, em 1 Cl quarenta e três vezes, em Dg sete vezes, em Js duas vezes, uma vez em cada um de Jd, Rv, 2 Cl, B. Não se encontra de modo algum em Mk, Gal, Col, 1 e 2 Th, 1 e 2 Ti, Tit, 1, 2 e 3 J, 1 e 2 Pt, GJs. De longe mais frequente [cerca de 150 vezes] em Ac (cf. o uso frequente em Polyb.). A tradição manuscrita frequentemente confunde <span class=\"greek\">τέ</span> e <span class=\"greek\">δέ</span>.—B-D-F §443f; Rdm.2 p. 5f, 37; Rob. índice p. 1285; Mlt.-Turner 338.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> marcador de estreita relação entre estados ou acontecimentos sucessivos, e igualmente, e assim, assim (B-D-F §443, 3; TestJob 24:1; 53:5; Just., A II, 4, 2) <span class=\"greek\">ἑτέροις</span> <span class=\"greek\">τε</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">πλείοσιν</span> <span class=\"greek\">διεμαρτύρατο</span> e igualmente … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a> (aqui D tem a leitura inferior <span class=\"greek\">δέ</span>). <span class=\"greek\">κατενύγησαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span>, <span class=\"greek\">εἶπόν</span> <span class=\"greek\">τε</span> … , e assim disseram v. 37.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:42</a>; 6:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:33</a>; 5:19, 35; 6:7, 12f al.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>; Jd 6.—O emprego de <span class=\"greek\">τέ</span> para introduzir um parêntese é dificilmente admissível; deve-se preferir <span class=\"greek\">δέ</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:15</a>; 4:13 (v. B-D-F §443, 1; 447, 7).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> marcador de conexão entre elementos coordenados não sucessivos</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> empregado isoladamente, e: <span class=\"greek\">τέ</span> conecta assim conceitos isolados, partes de orações ou palavras (Just., A II, 11, 4; v. Kühner-G. II 241; Schwyzer II 574–76; Denniston 497–503) <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">πνεύματί</span> <span class=\"greek\">τε</span> <span class=\"greek\">πραΰτητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:21</a>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τε</span> <span class=\"greek\">μέλλοντος</span> <span class=\"greek\">αἰῶνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:5</a>. Cf. 9:1. <span class=\"greek\">ἔκλασεν</span> <span class=\"greek\">ἄρτον</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">τε</span> <span class=\"greek\">προσήνεγκεν</span> AcPl Ha 4, 4; oração relativa <span class=\"greek\">ἅ</span> <span class=\"greek\">τε</span> <span class=\"greek\">Ἀριστίων</span> … <span class=\"greek\">λέγουσιν</span> Papias (2:4). Particípios: <span class=\"greek\">συναχθέντες</span> <span class=\"greek\">συμβούλιόν</span> <span class=\"greek\">τε</span> <span class=\"greek\">λαβόντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:12</a>; <span class=\"greek\">φοβούμενος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">μαρτυρούμενός</span> <span class=\"greek\">τε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:33</a>; 20:11; 28:23a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>; 6:4. Infinitivos: <span class=\"greek\">ἁρπάσαι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἄγειν</span> <span class=\"greek\">τε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:10</a>; cf. 11:26; 24:23; 27:21b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:19</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> <span class=\"greek\">τὲ</span> … <span class=\"greek\">τέ</span>, empregado como conector de frases e partes de frases estreitamente relacionadas entre si assim como … assim também, não somente … mas também (Kühner-G. II 243; Schwyzer II 573f; Denniston 503–5; Jos., Ant. 1, 92) <span class=\"greek\">μάρτυρα</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">τε</span> <span class=\"greek\">εἶδές</span> <span class=\"greek\">με</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ὀφθήσομαί</span> <span class=\"greek\">σοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:16</a> (sobre a constr., v. <span class=\"greek\">ὁράω</span> A1b). <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ζῶμεν</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">ζῶμεν</span>, <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἀποθνῄσκωμεν</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">ἀποθνῄσκομεν</span> pois, assim como, quando vivemos, vivemos para o Senhor, assim também, quando morremos, morremos para o Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:8a</a>. <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ζῶμεν</span> <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἀποθνῄσκωμεν</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐσμέν</span> portanto, não somente se vivemos, mas também se morremos (isto é, quer vivamos, quer morramos), pertencemos ao Senhor v. 8b. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46</a>; 17:4; 26:10. <span class=\"greek\">τε</span> <span class=\"greek\">γάρ</span> ‘pois o fato é que’ é uma maneira de traduzir esta combinação (X., Mem. 1, 1, 3; Just., D. 3, 5; Ath. 2, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:26</a>; 7:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:11</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> com a mesma acepção <span class=\"greek\">τὲ</span> … <span class=\"greek\">καί</span> (Jos., Bell. 2, 142, Ant. 1, 9) e <span class=\"greek\">τὲ</span> <span class=\"greek\">καί</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. conectando conceitos, geralmente da mesma espécie ou correspondentes como opostos. Nestes usos <span class=\"greek\">τὲ</span> <span class=\"greek\">καί</span> pode frequentemente ser traduzido simplesmente por e: <span class=\"greek\">δῶρά</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυσίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a>. <span class=\"greek\">δεήσεις</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱκετηρίας</span> v. 7. <span class=\"greek\">ὀνειδισμοῖς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θλίψεσιν</span> 10:33. <span class=\"greek\">φόβητρά</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11b</a>. Cf. 22:66; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:27</a>; 26:3. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:1</a>. <span class=\"greek\">ἀσφαλῆ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βεβαίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:19</a>. <span class=\"greek\">πάντῃ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πανταχοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:3</a>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a> v.l. <span class=\"greek\">παρά</span> <span class=\"greek\">τε</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">κἀκείνων</span> AcPlCor 1:5. <span class=\"greek\">πονηρούς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγαθούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a>. <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γυναῖκες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:12</a>; 9:2; 22:4. <span class=\"greek\">Ἰουδαίοις</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἕλλησιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:24</a>. <span class=\"greek\">μικρῷ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:22a</a>. Quando empregado com um substantivo que tem art., <span class=\"greek\">τέ</span> vem depois deste último: <span class=\"greek\">ὅ</span> <span class=\"greek\">τε</span> <span class=\"greek\">στρατηγὸς</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρχιερεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:24</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:38</a>; 17:10; 27:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:11</a>. <span class=\"greek\">ἰχῶράς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκώληκας</span> Papias (3:2). <span class=\"greek\">ψαλμῶν</span> <span class=\"greek\">τε</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ᾠδῶν</span> AcPl Ha 7, 11.—<span class=\"greek\">τέ</span> pode ser seguido de mais de um <span class=\"greek\">καί</span> (Ar. 3, 1 <span class=\"greek\">ἡλίου</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σελήνης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λοιπῶν</span> <span class=\"greek\">στοιχείων</span>; 4:1 <span class=\"greek\">ἀφθαρτός</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναλλοίωτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀόρατος</span>; Just., D. 126, 5; Libanius, Or. 2 p. 256, 6 F.) <span class=\"greek\">τήν</span> <span class=\"greek\">τε</span> <span class=\"greek\">Μαριὰμ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βρέφος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:16</a>. <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίνειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεθύσκεσθαι</span> 12:45. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>; 9:2.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:30</a> <span class=\"greek\">τὲ</span> <span class=\"greek\">καί</span> conecta o segundo e o terceiro membros de uma série, e outro <span class=\"greek\">καί</span> liga o quarto. Analogamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:32</a>. <span class=\"greek\">τὲ</span> <span class=\"greek\">καί</span> duplicado: <span class=\"greek\">Ἕλλησίν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βαρβάροις</span>, <span class=\"greek\">σοφοῖς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνοήτοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:14</a>. <span class=\"greek\">θηρίων</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πετεινῶν</span> <span class=\"greek\">ἑρπετῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐναλίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:7</a>.—<span class=\"greek\">τὲ</span> <span class=\"greek\">καὶ</span> … <span class=\"greek\">τέ</span>: <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασιλέων</span> <span class=\"greek\">υἱῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:15</a>. Cf. 26:10f. O <span class=\"greek\">τὲ</span> <span class=\"greek\">καὶ</span> … <span class=\"greek\">τὲ</span> … <span class=\"greek\">καί</span> do v. 20 parece dever-se a um erro textual.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. raramente conectando frases inteiras (Mayser II/3, 160; 163f; 165) <span class=\"greek\">ἠνεῴχθησάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">θύραι</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δεσμὰ</span> <span class=\"greek\">ἀνέθη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:26</a> v.l. <span class=\"greek\">καὶ</span> … , <span class=\"greek\">καὶ</span> … <span class=\"greek\">τὲ</span> … , <span class=\"greek\">καί</span> 2:2–4 v.l. <span class=\"greek\">τὲ</span> …, <span class=\"greek\">καὶ</span> … , <span class=\"greek\">καί</span> 21:30.—Sobre <span class=\"greek\">εἴτε</span> v. <span class=\"greek\">εἰ</span> 6o. Sobre <span class=\"greek\">μήτε</span> v. esse verbete.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> marcador com ênfase ascensiva e funcionando sem força copulativa, até mesmo <span class=\"greek\">ἐάν</span> <span class=\"greek\">τε</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">περισσότερόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">καυχήσωμαι</span> pois suponhamos que eu (até) me glorie um pouco demais (Goodsp.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:7</a> (sobre desenvolvimentos helen. v. Rdm.2 5f; B-D-F §443, 3: com sugestão de provável supressão de um segundo <span class=\"greek\">τε</span>).—CRuigh, Antour de <span class=\"greek\">τέ</span> epique, études sur la syntax grecque, Amsterdam ’70.—DELG. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέγος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέγος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. [Od.]+; Lucian; Aelian, NA 2, 48 p. 56, 11; Jos., Bell. 1, 337, Ant. 17, 71; Just., A I, 26, 3; SibOr 3, 186) teto: <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέγος</span> sob o teto (guiar, como Appian, Bell. Civ. 4, 18 §70) 1 Cl 12:6 (como a leitura preferida a <span class=\"greek\">στέγος</span> por Lghtf.; a mesma confusão de leituras em EpJer 9).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθεικα, τεθεικώς, τέθειται, τεθῆναι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέθεικα</span>, <span class=\"greek\">τεθεικώς</span>, <span class=\"greek\">τέθειται</span>, <span class=\"greek\">τεθῆναι</span> v. <span class=\"greek\">τίθημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθλιμμένος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεθλιμμένος</span> v. <span class=\"greek\">θλίβω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθνάναι, τέθνηκα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεθνάναι</span>, <span class=\"greek\">τέθνηκα</span> v. <span class=\"greek\">θνῄσκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέθραμμαι, τεθραμμένος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέθραμμαι</span>, <span class=\"greek\">τεθραμμένος</span> v. <span class=\"greek\">τρέφω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεθῶ</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεθῶ</span> v. <span class=\"greek\">τίθημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0354-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεῖχος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεῖχος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom.+; empréstimo na lit. rabínica; ‘muro’, frequentemente destinado à defesa) muro, especialmente muralha de cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:33</a> (<span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τείχους</span> como em Jos., Ant. 5, 15. Cf. Athen. 5, 214a <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τειχῶν</span> <span class=\"greek\">καθιμήσαντας</span> <span class=\"greek\">φεύγειν</span>; v. também Plut., Aemil. Paul. 269 [26]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:12</a>, 14f, 17–19 (sobre associação com pessoas v. Reader, Polemo 264f, 375). Pl. de diversos muros circulares que circundam a torre em Hermas: Hs 8, 2, 5; 8, 6, 6; 8, 7, 3; 8, 8, 3.—B. 472. DELG. M-M.</p></section></article>"};
